"""Runtime storage adapters. Keys are generated by the host, never by models."""
import os

from .filesystem import FilesystemBlobStore
from .s3 import S3BlobStore


def filesystem_from_env() -> FilesystemBlobStore:
    return FilesystemBlobStore(os.environ.get('UAI_STORAGE_DIR', 'data/blobs'))


__all__ = ['FilesystemBlobStore', 'S3BlobStore', 'filesystem_from_env']
